(() => {
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  class PenaltyDuelRenderer {
    constructor(canvas) { this.canvas = canvas; this.ctx = canvas?.getContext?.('2d'); this.width = 390; this.height = 760; this.flash = 0; this.flashColor = '#fff'; this.shake = 0; this.trail = []; this.motion = 0; this.resize(); }
    visual(slot = null) { return window.TelePlayShop?.visualForGame?.('penalty-duel', slot) || { color: '#9dffff', accent: '#36a9ef' }; }
    fade(value, alpha = 1) { const raw = String(value || '').replace('#', ''); if (raw.length !== 6) return value; const n = parseInt(raw, 16); return `rgba(${n >> 16},${(n >> 8) & 255},${n & 255},${alpha})`; }
    resize() { if (!this.canvas) return; const dpr = Math.min(2, window.devicePixelRatio || 1), rect = this.canvas.getBoundingClientRect(); this.width = Math.max(280, rect.width || this.canvas.clientWidth || 390); this.height = Math.max(440, rect.height || this.canvas.clientHeight || 760); this.canvas.width = this.width * dpr; this.canvas.height = this.height * dpr; this.ctx?.setTransform(dpr, 0, 0, dpr, 0, 0); }
    effect(color = '#fff', shake = 0) { this.flash = .35; this.flashColor = color; this.shake = shake; }
    render(s = {}) {
      const c = this.ctx; if (!c) return; const w = this.width, h = this.height, now = performance.now();
      c.save();
      if (this.shake) { c.translate((Math.random() - .5) * this.shake, (Math.random() - .5) * this.shake); this.shake *= .82; if (this.shake < .1) this.shake = 0; }
      const stadium = this.visual('stadiums');
      const bg = c.createLinearGradient(0, 0, 0, h); bg.addColorStop(0, this.fade(stadium.accent, .34)); bg.addColorStop(.6, this.fade(stadium.color, .16)); bg.addColorStop(1, '#07111e'); c.fillStyle = bg; c.fillRect(0, 0, w, h);
      const glow = c.createRadialGradient(w * .5, h * .25, 8, w * .5, h * .28, w * .82); glow.addColorStop(0, this.fade(stadium.accent, .28)); glow.addColorStop(1, '#02040d00'); c.fillStyle = glow; c.fillRect(0, 0, w, h);
      this.motion += s.keeperJump ? .16 : .04; this.drawField(c, w, h); this.drawGoal(c, w, h, s.zoneId); this.drawKeeper(c, w, h, s.keeperDirection, s.keeperSaving, s.keeperJump, s.saveFx);
      const ball = s.ball || { x: w * .5, y: h * .78, z: 0 }; const bx = ball.x || w * .5, by = (ball.y || h * .78) - (ball.z || 0) * .26;
      if (s.state === 'flying') { this.trail.push({ x: bx, y: by, t: now }); if (this.trail.length > 14) this.trail.shift(); }
      const visual = this.visual('balls'); this.trail = this.trail.filter(p => now - p.t < 400); this.trail.forEach((p, i) => { const a = (i + 1) / this.trail.length * .28; c.globalAlpha = a; c.fillStyle = visual.color; c.beginPath(); c.arc(p.x, p.y, 3 + i * .25, 0, Math.PI * 2); c.fill(); c.globalAlpha = 1; });
      this.drawBall(c, bx, by, s.state === 'flying' ? 1.2 : 1);
      if (s.saveFx) this.drawSaveImpact(c, bx, by);
      if (s.swipeStart && s.swipeCurrent && s.state === 'ready') this.drawAim(c, s.swipeStart, s.swipeCurrent);
      if (this.flash > 0) { c.globalAlpha = clamp(this.flash * .32, 0, .32); c.fillStyle = this.flashColor; c.fillRect(0, 0, w, h); c.globalAlpha = 1; this.flash -= .018; }
      c.restore();
    }
    drawField(c, w, h) { const stadium = this.visual('stadiums'); c.strokeStyle = this.fade(stadium.color, .14); c.lineWidth = 1; for (let y = h * .5; y < h; y += 38) { c.beginPath(); c.moveTo(0, y); c.lineTo(w, y); c.stroke(); } c.fillStyle = this.fade(stadium.accent, .08); c.fillRect(w * .08, h * .6, w * .84, 1); c.strokeStyle = this.fade(stadium.color, .28); c.beginPath(); c.ellipse(w * .5, h * .83, w * .38, 54, 0, Math.PI, Math.PI * 2); c.stroke(); }
    drawGoal(c, w, h, activeId) { const r = window.PenaltyDuelGoalSystem.goalRect(w, h), zs = window.PenaltyDuelGoalSystem.zones(w, h); c.save(); c.shadowBlur = 22; c.shadowColor = '#6df5ff66'; c.strokeStyle = '#87f8ff'; c.lineWidth = 3; c.strokeRect(r.x, r.y, r.width, r.height); c.shadowBlur = 0; zs.forEach(z => { c.fillStyle = z.id === activeId ? '#7ef5ff2e' : '#b7c9ff08'; c.fillRect(z.rect.x, z.rect.y, z.rect.width, z.rect.height); c.strokeStyle = '#9abaff24'; c.strokeRect(z.rect.x, z.rect.y, z.rect.width, z.rect.height); }); c.restore(); }
    drawKeeper(c, w, h, direction, saving, jumping = 0, saveFx = false) { const r = window.PenaltyDuelGoalSystem.goalRect(w, h), side = direction === 'left' ? -1 : direction === 'right' ? 1 : 0, bounce = jumping ? Math.sin(this.motion) * 5 : 0, cx = r.x + r.width * .5 + side * r.width * .22 * jumping, cy = r.y + r.height * .76 - 12 * jumping + bounce, bodyW = 48, bodyH = 72, reach = saveFx ? 58 : (jumping ? 46 : 30); c.save(); c.translate(cx, cy); c.rotate(side * .14 * jumping); c.shadowBlur = saving ? 28 : 16; c.shadowColor = saving ? '#ff75bd' : '#be8dff'; c.fillStyle = saving ? '#ff70b8' : '#9f8aff'; c.beginPath(); if (c.roundRect) c.roundRect(-bodyW / 2, -bodyH, bodyW, bodyH, 14); else c.rect(-bodyW / 2, -bodyH, bodyW, bodyH); c.fill(); c.fillStyle = '#f5f8ff'; c.beginPath(); c.arc(0, -bodyH - 17, 15, 0, Math.PI * 2); c.fill(); c.strokeStyle = saving ? '#fff6fd' : '#d8d2ff'; c.lineWidth = 8; c.lineCap = 'round'; c.beginPath(); if (side < 0) { c.moveTo(-18, -bodyH + 22); c.lineTo(-reach - 16, -bodyH + 6); c.moveTo(12, -bodyH + 24); c.lineTo(28, -bodyH + 34); } else if (side > 0) { c.moveTo(18, -bodyH + 22); c.lineTo(reach + 16, -bodyH + 6); c.moveTo(-12, -bodyH + 24); c.lineTo(-28, -bodyH + 34); } else { c.moveTo(-16, -bodyH + 20); c.lineTo(-reach, -bodyH + 2); c.moveTo(16, -bodyH + 20); c.lineTo(reach, -bodyH + 2); } c.stroke(); c.fillStyle = saving ? '#fff' : '#d8d2ff'; c.beginPath(); if (side < 0) { c.arc(-reach - 17, -bodyH + 4, 8, 0, Math.PI * 2); } else if (side > 0) { c.arc(reach + 17, -bodyH + 4, 8, 0, Math.PI * 2); } else { c.arc(-reach, -bodyH + 1, 8, 0, Math.PI * 2); c.arc(reach, -bodyH + 1, 8, 0, Math.PI * 2); } c.fill(); c.restore(); }
    drawBall(c, x, y, scale) { const visual = this.visual('balls'); c.save(); c.shadowBlur = 24; c.shadowColor = visual.color; const g = c.createRadialGradient(x - 3, y - 4, 1, x, y, 11 * scale); g.addColorStop(0, '#fff'); g.addColorStop(.28, visual.color); g.addColorStop(1, visual.accent); c.fillStyle = g; c.beginPath(); c.arc(x, y, 10 * scale, 0, Math.PI * 2); c.fill(); c.restore(); }
    drawSaveImpact(c, x, y) { const visual = this.visual('goal-effects'); c.save(); const pulse = 1 + Math.sin(this.motion * 3) * .16; c.strokeStyle = this.fade(visual.color, .68); c.lineWidth = 3; c.shadowBlur = 20; c.shadowColor = visual.color; c.beginPath(); c.arc(x, y, 26 * pulse, 0, Math.PI * 2); c.stroke(); c.strokeStyle = '#fff'; c.lineWidth = 2; for (let i = 0; i < 6; i++) { const a = i * Math.PI / 3 + this.motion; c.beginPath(); c.moveTo(x + Math.cos(a) * 17, y + Math.sin(a) * 17); c.lineTo(x + Math.cos(a) * 34, y + Math.sin(a) * 34); c.stroke(); } c.restore(); }
    drawAim(c, a, b) { c.save(); c.strokeStyle = '#65f1ffbb'; c.setLineDash([6, 8]); c.lineWidth = 2; c.beginPath(); c.moveTo(a.x, a.y); c.lineTo(b.x, b.y); c.stroke(); c.setLineDash([]); c.fillStyle = '#65f1ff'; c.beginPath(); c.arc(b.x, b.y, 5, 0, Math.PI * 2); c.fill(); c.restore(); }
  }
  window.PenaltyDuelRenderer = PenaltyDuelRenderer;
})();
